                                gsap.fromTo('#risk-loader-card', { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3, ease: 'power2.out' });
                                gsap.to('#risk-progress-fill', { width: '100%', duration: 0.55, ease: 'power2.out' });
